              "- GV dẫn dắt tích hợp AI: Trong gia đình hiện nay có thể có loa thông minh, robot hút bụi, ti vi thông minh, máy giặt thông minh hoặc điện thoại có trợ lí ảo. Một số thiết bị dùng AI để hỗ trợ con người nhận lệnh, gợi ý hoặc tự động thực hiện công việc.\n- GV diễn giải: Thiết bị thông minh đem lại tiện nghi nhưng không phải đồ chơi. HS chỉ sử dụng khi được người lớn cho phép; không làm ướt, va đập, che cảm biến, kéo dây điện, bấm nhiều nút hoặc ra lệnh tùy tiện. Khi thiết bị hoạt động bất thường, cần dừng sử dụng và báo người lớn.\n- GV hỏi: Em biết thiết bị thông minh nào trong nhà? Em sẽ bảo quản thiết bị đó như thế nào?\n- GV nhấn mạnh: AI có thể hỗ trợ nhưng con người vẫn phải chịu trách nhiệm sử dụng đúng mục đích, kiểm tra và giữ gìn thiết bị; không phụ thuộc hoặc tự ý thay đổi cài đặt.",
              "- HS kể tên một số thiết bị thông minh quen thuộc.\n- HS nêu quy tắc sử dụng an toàn, có sự hướng dẫn của người lớn.\n- HS trả lời bằng một việc cụ thể: giữ khô, đặt đúng chỗ, không bấm lung tung, không che cảm biến và báo người lớn khi có lỗi.\n- HS ghi nhớ vai trò của bản thân trong việc bảo quản thiết bị."
